internal static class SwitchTableChecks
{
    private static void U16(byte[] b,int at,int v)=>BinaryPrimitives.WriteUInt16LittleEndian(b.AsSpan(at),(ushort)v);
    private static void I32(byte[] b,int at,int v)=>BinaryPrimitives.WriteInt32LittleEndian(b.AsSpan(at),v);
    private static byte[] Gift(int species)
    {var b=new byte[80];I32(b,0,12);U16(b,4,6);U16(b,6,8);U16(b,8,4);I32(b,12,8);I32(b,16,4);I32(b,20,1);I32(b,24,40);U16(b,28,24);U16(b,30,16);U16(b,34,8);U16(b,48,9);U16(b,50,4);I32(b,64,36);I32(b,68,species);b[73]=5;return b;}
    internal static void Run(Action<bool,string> check,Action<Action,string> reject)
    {
        check(new[]{"Hop","Paul","Marnie","Roxy","Bede","Berto"}.All(n=>SwordShieldProject.ClassifyTrainerName(n)=="Importantes · Rivales")&&SwordShieldProject.ClassifyTrainerName("Milo").StartsWith("Jefes")&&SwordShieldProject.ClassifyTrainerName("Youngster")=="Normal","Switch_Tables_ClassifiesRivalsSeparatelyFromGymLeaders");
        var source=SwitchParityChecks.Inputs();const string path="bin/trainer/trainer_poke/trainer_poke_001.bin";var rules=new SwordShieldTrainerOptions {MoveRules=new[]{new SwordShieldTrainerMoveRule(1,true,true,40,0,false)}};
        var selected=SwordShieldGameplay.Generate(source,SwordShieldChecks.Table(),false,new(123,Trainers:true){RandomizeTrainerSpecies=false,TrainerRules=rules}).Files()[path];
        check(BinaryPrimitives.ReadUInt16LittleEndian(selected.AsSpan(18))==2&&BinaryPrimitives.ReadUInt16LittleEndian(selected.AsSpan(20))==0,"Switch_Tables_PerTrainerMoveRuleChangesFinalMoves");
        var other=SwordShieldGameplay.Generate(source,SwordShieldChecks.Table(),false,new(123,Trainers:true){RandomizeTrainerSpecies=false,TrainerRules=rules with{MoveRules=new[]{new SwordShieldTrainerMoveRule(2,true,true,40,0,false)}}});check(other.Changes.Count==0,"Switch_Tables_PerTrainerMoveRuleLeavesOtherTrainerUntouched");
        reject(()=>SwordShieldBattlePolicy.Validate(new(1){TrainerRules=rules with{MoveRules=new[]{new SwordShieldTrainerMoveRule(1,true,false,256,15,true)}}}),"Switch_Tables_InvalidIndividualMoveRuleRejected");
        var member=SwordShieldGameplayChecks.Encounter();I32(member,184,0);member[180]=0;var archive=SwordShieldGameplayChecks.Pack("encount_k.bin",member);var world=new Dictionary<string,byte[]>{{SwordShieldGameplay.EncountersPath,archive}};
        check(SwordShieldGameplay.Generate(world,SwordShieldChecks.Table(),false,new(12,HiddenEncounters:true)).Changes.Count==0,"Switch_Tables_EmptySlotsRemainUntouchedByDefault");
        var filled=SwordShieldGameplay.Generate(world,SwordShieldChecks.Table(),false,new(12,HiddenEncounters:true){FillEmptyEncounters=true});var output=new SwitchGfPack(filled.Files()[SwordShieldGameplay.EncountersPath]).Read(0);check(BinaryPrimitives.ReadInt32LittleEndian(output.AsSpan(184))>0&&output[180]==100&&member[180]==0&&BinaryPrimitives.ReadInt32LittleEndian(member.AsSpan(184))==0,"Switch_Tables_FillEmptySlotAssignsSpeciesAndValidProbabilityWithoutSourceWrite");
        var omitted=SwordShieldGameplayChecks.Encounter();U16(omitted,164,0);U16(omitted,166,0);U16(omitted,168,0);U16(omitted,116,0);U16(omitted,118,0);var beforeOmitted=(byte[])omitted.Clone();var expanded=SwordShieldEncounterExpansion.Materialize(omitted,"encount_k.bin",null);var expandedFb=new SwitchFlatBuffer(expanded);int expandedZone=expandedFb.Tables(expandedFb.Root,1,true).Single(),expandedSub=expandedFb.Tables(expandedZone,1,true).Single(),expandedSlot=expandedFb.Tables(expandedSub,2,true).Single();check(expanded.Length>omitted.Length&&expandedFb.Field(expandedSlot,1,4)>=0&&omitted.SequenceEqual(beforeOmitted)&&Enumerable.Range(0,omitted.Length).Where(i=>i<100||i>=104).All(i=>omitted[i]==expanded[i]),"Switch_Tables_MaterializesOmittedFieldsPreservingOriginalBytesExceptSelectedReference");
        check(SwordShieldEncounterExpansion.Materialize(omitted,"encount_k.bin",new[]{"encount_k.bin/1/0"}).SequenceEqual(omitted),"Switch_Tables_MaterializationPreservesUnselectedRegions");
        var alias=(byte[])omitted.Clone();I32(alias,48,2);I32(alias,56,24);reject(()=>SwordShieldEncounterExpansion.Materialize(alias,"encount_k.bin",new[]{"encount_k.bin/0/0"}),"Switch_Tables_ExpansionRejectsScopeSplittingSharedSubtableReferences");
        var unknown=(byte[])omitted.Clone();U16(unknown,160,12);U16(unknown,170,4);reject(()=>SwordShieldEncounterExpansion.Materialize(unknown,"encount_k.bin",null),"Switch_Tables_ExpansionRejectsUnknownSlotFieldsBeforeWriting");
        var omittedWorld=new Dictionary<string,byte[]>{{SwordShieldGameplay.EncountersPath,SwordShieldGameplayChecks.Pack("encount_k.bin",omitted)}};var filledOmitted=SwordShieldGameplay.Generate(omittedWorld,SwordShieldChecks.Table(),false,new(12,HiddenEncounters:true){FillEmptyEncounters=true});var filledFb=new SwitchFlatBuffer(new SwitchGfPack(filledOmitted.Files()[SwordShieldGameplay.EncountersPath]).Read(0));int z=filledFb.Tables(filledFb.Root,1,true).Single(),sub=filledFb.Tables(z,1,true).Single(),sl=filledFb.Tables(sub,2,true).Single();check(filledFb.I32(filledFb.Field(sl,1,4))>0&&filledFb.Data[filledFb.Field(sl,0,1)]==100&&filledFb.Data[filledFb.Field(sub,0,1)]==1&&filledFb.Data[filledFb.Field(sub,1,1)]==5,"Switch_Tables_FillsPhysicallyOmittedSlotsAndLevelsWithValidReopenedData");
        var personal=SwordShieldChecks.Table();for(int i=0;i<6;i++)personal[3*176+i]=200;
        var gifts=new Dictionary<string,byte[]>{{SwordShieldDataEditor.EventPath(SwordShieldDataSection.Gifts),Gift(1)}};
        for(uint seed=0;seed<12;seed++){var result=SwordShieldDataEditor.Randomize(SwordShieldDataSection.Gifts,gifts,personal,new(seed,SimilarBst:true));var combined=new Dictionary<string,byte[]>(gifts);foreach(var p in result.Files())combined[p.Key]=p.Value;int species=SwordShieldDataEditor.Read(SwordShieldDataSection.Gifts,combined,personal).Single(c=>c.Field=="Especie").Value;check(species is 1 or 2,"Switch_Tables_GiftBstFiltersDistantSpecies_"+seed);}
        Array.Copy(personal,176,personal,810*176,176);gifts[SwordShieldDataEditor.EventPath(SwordShieldDataSection.Gifts)]=Gift(810);var e1=new byte[72];U16(e1,0,4);U16(e1,4,2);e1[7]=16;var e2=new byte[72];U16(e2,0,4);U16(e2,4,3);e2[7]=36;gifts["bin/pml/evolution/evo_001.bin"]=e1;gifts["bin/pml/evolution/evo_002.bin"]=e2;
        var starters=SwordShieldDataEditor.Randomize(SwordShieldDataSection.Gifts,gifts,personal,new(25,ThreeStageStarters:true));check(starters.Changes.Single(c=>c.Field=="Especie").After==1,"Switch_Tables_StartersUseActualThreeStageEvolutionGraph");
        gifts[SwordShieldDataEditor.EventPath(SwordShieldDataSection.Gifts)]=Gift(2);var again=SwordShieldDataEditor.Randomize(SwordShieldDataSection.Gifts,gifts,personal,new(25,ThreeStageStarters:true){StarterEntries=new[]{0}});check(again.Changes.Single(c=>c.Field=="Especie").After==1,"Switch_Tables_StarterRecordIdentitySurvivesPreviousRandomization");
        gifts.Remove("bin/pml/evolution/evo_002.bin");reject(()=>SwordShieldDataEditor.Randomize(SwordShieldDataSection.Gifts,gifts,personal,new(25,ThreeStageStarters:true)),"Switch_Tables_StarterFilterRejectsMissingThreeStageCandidates");
    }
    internal static void RunUi(Action<bool,string> check)
    {
        string temp=Path.Combine(Path.GetTempPath(),"dr-table-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);try
        {
            string root=SwordShieldChecks.Fixture(temp,"source");foreach(var pair in SwitchParityChecks.Inputs()){string p=Path.Combine(root,"romfs",pair.Key);Directory.CreateDirectory(Path.GetDirectoryName(p)!);File.WriteAllBytes(p,pair.Value);}var project=SwordShieldProject.Open(root);
            foreach(var section in new[]{SwordShieldDataSection.Learnsets,SwordShieldDataSection.Machines,SwordShieldDataSection.Items}){var editor=new SwordShieldRecordEditor(project,section);var view=new RecordEditorView(editor);check(view.ActiveRecordTable is {} table&&table.Items.Count>0&&table.FrozenColumnCount==1,"Switch_Tables_UsesEditableGrid_"+section);if(section==SwordShieldDataSection.Learnsets){var control=(System.Windows.Controls.TextBox)view.FieldControls.First(p=>p.Value is System.Windows.Controls.TextBox).Value;control.Text="9";var values=view.FieldControls.ToDictionary(p=>p.Key,p=>p.Value is System.Windows.Controls.TextBox text?int.Parse(text.Text):p.Value is System.Windows.Controls.ComboBox combo?(int)combo.SelectedValue:((System.Windows.Controls.CheckBox)p.Value).IsChecked==true?1:0);editor.Save(editor.Entries[0].Id,values);check(project.DataHistory.Count==1,"Switch_Tables_GridEditsUseExistingValidatedSaveAndHistory");}}
            var trainerView=new RecordEditorView(new SwordShieldRecordEditor(project,SwordShieldDataSection.TrainerTeams));foreach(var buttonName in new[]{"TrainerCapsButton"}){((System.Windows.Controls.Button)trainerView.FindName(buttonName)).RaiseEvent(new System.Windows.RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));var host=(System.Windows.Controls.ContentControl)trainerView.FindName("TrainerRulesHost");check(host.Content is System.Windows.Controls.Border surface&&surface.Background is not null&&trainerView.ActiveTrainerRuleGrid?.FrozenColumnCount==2,"Switch_Tables_OpaqueFullWidthRuleTable_"+buttonName);var panel=(System.Windows.Controls.DockPanel)((System.Windows.Controls.Border)host.Content).Child;panel.Children.OfType<System.Windows.Controls.WrapPanel>().SelectMany(p=>p.Children.OfType<System.Windows.Controls.Button>()).Single(b=>b.Content.ToString()=="Cancelar").RaiseEvent(new System.Windows.RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));check(host.Visibility==System.Windows.Visibility.Collapsed,"Switch_Tables_CancelClosesRuleTable_"+buttonName);}
            var economy=new SwordShieldRecordEditor(project,SwordShieldDataSection.Items);var prices=economy.PriceRows();foreach(var row in prices)row.Included=false;var first=prices[0];first.Included=true;first.TargetBuy=200;var proposal=economy.PreviewEconomy(prices);check(proposal.Changes.Count==1,"Switch_Tables_FixEconomyPreviewUsesOnlySelectedMoneyPrice");economy.Apply(proposal);check(project.ReadData(SwordShieldDataSection.Items).Single(c=>c.Entry==first.Id&&c.Field=="Precio").Value==200,"Switch_Tables_FixEconomyAppliesAndReopensPrice");
        }finally{Directory.Delete(temp,true);}
    }
    internal static void Probe(string root)
    {
        var project=SwordShieldProject.Open(root);
        foreach(var section in new[]{SwordShieldDataSection.Statics,SwordShieldDataSection.Gifts}){var options=new SwordShieldDataOptions(12345,SimilarBst:true,ThreeStageStarters:section==SwordShieldDataSection.Gifts);var preview=project.PreviewData(section,null,options);Console.WriteLine("PASS Switch_Tables_RealBstPreview_"+section+": "+preview.Result.Changes.Count+" changes; starters="+(preview.Options?.StarterEntries?.Count??0));}
        var trainer=new SwordShieldRecordEditor(project,SwordShieldDataSection.TrainerTeams);var values=EditorValues.Flatten(trainer.RandomOptions);values["Species"]=0;values["Rule.7.CapUse"]=1;values["Rule.7.LevelCap"]=30;values["GlobalMoves.Better"]=1;var proposal=trainer.Preview(values,new[]{7});if(!proposal.Changes.Any(c=>c.Field=="Nivel"))throw new Exception("Rival cap not applied.");Console.WriteLine("PASS Switch_Tables_RealSelectedRivalCapsAndGeneralMovesPreview: "+proposal.Changes.Count+" changes");
        var archive=File.ReadAllBytes(Path.Combine(root,"romfs",SwordShieldGameplay.EncountersPath));var pack=new SwitchGfPack(archive);int reserved=0,omitted=0,emptyVectors=0;
        foreach(string member in project.Identity.TitleId=="01008DB008C2C000"?new[]{"encount_symbol_t.bin","encount_t.bin"}:new[]{"encount_symbol_k.bin","encount_k.bin"}){var fb=new SwitchFlatBuffer(pack.Read(pack.Find(member)));foreach(int zone in fb.Tables(fb.Root,1,true))foreach(int sub in fb.Tables(zone,1,true)){var slots=fb.Tables(sub,2,true);if(slots.Length==0)emptyVectors++;foreach(int slot in slots){int at=fb.Field(slot,1,4);if(at<0)omitted++;else if(fb.I32(at)==0)reserved++;}}}
        var full=project.PreviewGameplay(new SwordShieldGameplayOptions(12345,VisibleEncounters:true,HiddenEncounters:true){FillEmptyEncounters=true});Console.WriteLine("PASS Switch_Tables_RealEmptySlotAudit: allocated="+reserved+"; omitted="+omitted+"; empty-vectors="+emptyVectors+"; filled="+full.Result.Changes.Count(c=>c.Field=="Especie"&&c.Before==0));var reopened=SwordShieldWorldData.Read(full.Result.Files(),false,project.Identity.TitleId=="01008DB008C2C000");if(reopened.Count==0)throw new Exception("Expanded world cannot reopen.");var world=new SwordShieldWorldEditor(project,false);int first=world.Entries[0].Id;string label=world.Entries[0].Name;project.ApplyGameplay(full);_ = world.Read(first);if(world.Entries.Single(e=>e.Id==first).Name!=label)throw new Exception("World identity changed after expansion.");Console.WriteLine("PASS Switch_Tables_RealExpandedWorldReopensAndKeepsSelectionIdentity: "+world.Entries.Count+" regions");Console.WriteLine("Source read-only; no export, SD install or gameplay test.");
    }
